function render_logo(string $variant = 'default', string $size = 'md', string $extraClass = ''): string {
    $isInverted = in_array($variant, ['inverted', 'on-dark', 'glass'], true);
    $iconPath = $isInverted ? asset('logo_icon_light.png') : asset('logo_icon.png');
    $textColor = $isInverted ? 'text-white' : 'text-[#352719]';
    $accentColor = ($variant === 'glass') ? 'text-[#D4AF65]' : ($isInverted ? 'text-[#C5A989]' : 'text-[#795C43]');

    $sizes = [
        'sm' => ['icon' => 'h-8 w-8 sm:h-8.5 sm:w-8.5', 'text' => 'text-base sm:text-lg', 'gap' => 'gap-2 sm:gap-2.5', 'tracking' => 'tracking-wider'],
        'md' => ['icon' => 'h-9 w-9 sm:h-10 sm:w-10', 'text' => 'text-lg sm:text-xl', 'gap' => 'gap-2.5 sm:gap-3', 'tracking' => 'tracking-wider'],
        'lg' => ['icon' => 'h-11 w-11 sm:h-12 sm:w-12', 'text' => 'text-xl sm:text-2xl', 'gap' => 'gap-3', 'tracking' => 'tracking-widest'],
    ];
    $s = $sizes[$size] ?? $sizes['md'];

    return '<span class="group inline-flex items-center shrink-0 select-none ' . $s['gap'] . ' ' . htmlspecialchars($extraClass, ENT_QUOTES, 'UTF-8') . '">'
        . '<span class="relative shrink-0 flex items-center justify-center">'
        . '<img src="' . htmlspecialchars($iconPath, ENT_QUOTES, 'UTF-8') . '" alt="ONPRINT Dubai Logo" class="' . $s['icon'] . ' object-contain shrink-0 transition-all duration-300 group-hover:scale-105" />'
        . '</span>'
        . '<span class="flex flex-col justify-center leading-none">'
        . '<span class="font-black uppercase font-display select-none transition-colors duration-200 ' . $textColor . ' ' . $s['text'] . ' ' . $s['tracking'] . '">'
        . 'ON<span class="' . $accentColor . '">PRINT</span>'
        . '</span></span></span>';
}
